import{af as a,z as t,J as i,ab as d}from"./chunks/framework.Cvdy85y1.js";const l=JSON.parse('{"title":"Adding your first device","description":"","frontmatter":{"sidebar":false},"headers":[],"relativePath":"guides/adding-your-first-device.md","filePath":"guides/adding-your-first-device.md"}'),r={name:"guides/adding-your-first-device.md"};function o(n,e,u,c,s,g){return t(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793207954000"},[...e[0]||(e[0]=[d('<h1 id="adding-your-first-device" tabindex="-1">Adding your first device <a class="header-anchor" href="#adding-your-first-device" aria-label="Permalink to &quot;Adding your first device&quot;">​</a></h1><ul><li><strong>Target Audience</strong>: First time users</li><li><strong>Difficulty</strong>: Easy</li><li><strong>Prerequisites</strong>: A Lightbug device that is not yet added to a Lightbug Cloud account.</li></ul><h2 id="guide" tabindex="-1">Guide <a class="header-anchor" href="#guide" aria-label="Permalink to &quot;Guide&quot;">​</a></h2><p>You first need to create a Lightbug Cloud account.</p><p>See <a href="/docs/pr/31/apps/cloud/creating-account#registration">Creating an account</a> for step by step documentation.</p><p>On initial account creation, you will be guided through an onboarding process, where you will be prompted to add a first device.</p><p>See <a href="/docs/pr/31/apps/cloud/creating-account#onboarding">Adding a device</a> for step by step documentation.</p><p>You&#39;ll then be shown a small guide of the Map and interface, as documented in <a href="/docs/pr/31/apps/cloud/creating-account#interface-guide">Interface guide</a>.</p><p>You are done! Your device is now added to your account and you can start tracking.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/L6u6FgG.png" alt="Lightbug Cloud Map" tabindex="0"><figcaption>Lightbug Cloud Map</figcaption></figure>',10)])])}const f=a(r,[["render",o]]);export{l as __pageData,f as default};
